-- V51: Configure Semester, Duration Weeks and Teaching Courses breakdown for Inxhinieri Informatike Master - Year 1
-- Program: Inxhinieri Informatike (Master Shkencor), Study Year: 1, Duration: 12 weeks

-- Step 1: Update SEMESTER and DURATION_WEEKS on COURSES table
UPDATE FTIAPP.COURSES SET SEMESTER = '1', DURATION_WEEKS = 12 WHERE COURSE_ID = 137; -- Procese stokastike dhe Statistikë
UPDATE FTIAPP.COURSES SET SEMESTER = '1', DURATION_WEEKS = 12 WHERE COURSE_ID = 138; -- Programim i avancuar
