-- Step 2: Clean up any dependent child tables referencing old TEACHING_COURSES for Year 1 Master Informatike
DELETE FROM FTIAPP.ATTENDANCE WHERE TEACHING_COURSE_ID IN (SELECT TEACHING_COURSE_ID FROM FTIAPP.TEACHING_COURSES WHERE COURSE_ID IN (137, 138, 139, 140, 141, 142, 143, 144, 145, 146));
DELETE FROM FTIAPP.GRADES WHERE TEACHING_COURSE_ID IN (SELECT TEACHING_COURSE_ID FROM FTIAPP.TEACHING_COURSES WHERE COURSE_ID IN (137, 138, 139, 140, 141, 142, 143, 144, 145, 146));
DELETE FROM FTIAPP.TOPICS WHERE TEACHING_COURSE_ID IN (SELECT TEACHING_COURSE_ID FROM FTIAPP.TEACHING_COURSES WHERE COURSE_ID IN (137, 138, 139, 140, 141, 142, 143, 144, 145, 146));
DELETE FROM FTIAPP.FAILED_COURSES WHERE TEACHING_COURSE_ID IN (SELECT TEACHING_COURSE_ID FROM FTIAPP.TEACHING_COURSES WHERE COURSE_ID IN (137, 138, 139, 140, 141, 142, 143, 144, 145, 146));
DELETE FROM FTIAPP.COURSE_SCHEDULE WHERE TEACHING_COURSE_ID IN (SELECT TEACHING_COURSE_ID FROM FTIAPP.TEACHING_COURSES WHERE COURSE_ID IN (137, 138, 139, 140, 141, 142, 143, 144, 145, 146));
DELETE FROM FTIAPP.TEACHING_COURSES_CLASSES WHERE TEACHING_COURSE_ID IN (SELECT TEACHING_COURSE_ID FROM FTIAPP.TEACHING_COURSES WHERE COURSE_ID IN (137, 138, 139, 140, 141, 142, 143, 144, 145, 146));
DELETE FROM FTIAPP.TEACHING_COURSES WHERE COURSE_ID IN (137, 138, 139, 140, 141, 142, 143, 144, 145, 146);

